export const pricing = pgTable(
  'pricing',
  {
    id: serial('id').primaryKey(),
    enterpriseHeading: varchar('enterprise_heading').default('Looking for a custom solution?'),
    enterpriseCtaLabel: varchar('enterprise_cta_label').default('Contact Sales'),
    enterpriseDescription: varchar('enterprise_description').default(
      'For high-volume production houses and enterprise teams requiring custom integrations, advanced security, and dedicated support.',
    ),
    metaTitle: varchar('meta_title'),
    metaDescription: varchar('meta_description'),
    metaImage: integer('meta_image_id').references(() => media.id, {
      onDelete: 'set null',
    }),
    updatedAt: timestamp('updated_at', { mode: 'string', withTimezone: true, precision: 3 }),
    createdAt: timestamp('created_at', { mode: 'string', withTimezone: true, precision: 3 }),
  },
  (columns) => [index('pricing_meta_image_idx').on(columns.metaImage)],
)

